def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse sequences
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_opp = op[-1]
    last_me = my[-1]

    # Counts
    opp_c = op.count('C')
    opp_d = n - opp_c
    opp_rate = opp_c / n

    # Recent window rates
    w = min(12, n)
    recent = op[-w:]
    rec_c = recent.count('C')
    rec_rate = rec_c / w

    # Defection streak at end
    def streak(seq, val):
        c = 0
        for x in reversed(seq):
            if x == val:
                c += 1
            else:
                break
        return c

    opp_d_streak = streak(op, 'D')
    opp_c_streak = streak(op, 'C')
    my_d_streak = streak(my, 'D')

    # Mutual cooperation streak at end
    mutual_cc = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C' and op[i] == 'C':
            mutual_cc += 1
        else:
            break

    remaining = 100 - n

    # --- Early exploration phase ---
    if n < 3:
        return 'C'

    # --- End-game exploitation ---
    # If opponent is highly cooperative, defect in the last few rounds.
    if remaining <= 4 and opp_rate > 0.6:
        if remaining <= 2:
            return 'D'
        if opp_d_streak == 0 and rng.random() < 0.6:
            return 'D'
        return 'C'

    # Punish hard against persistent defectors in final stretch
    if remaining <= 6 and opp_rate < 0.35:
        return 'D'

    # --- Strong detection of always-cooperator ---
    # If opponent almost never defected, exploit periodically but keep cooperation.
    if opp_d <= 1 and n >= 6:
        if remaining <= 3:
            return 'D'
        # occasional probe
        if n % 7 == 0 and remaining > 5:
            return 'D'
        return 'C'

    # --- Always-defector detection ---
    if opp_c <= 1 and n >= 4:
        return 'D'

    # --- Opponent just defected: retaliation / forgiveness ---
    if last_opp == 'D':
        # Long defection streak: retaliate consistently
        if opp_d_streak >= 3:
            return 'D'
        # Restart cooperation after isolated defect if opponent is generally good
        if opp_rate > 0.7 and opp_d_streak == 1 and remaining > 8:
            # sometimes retaliate once, sometimes forgive
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        # Against moderately cooperative, retaliate but be willing to forgive
        if opp_rate > 0.5:
            if opp_d_streak == 1 and rng.random() < 0.25:
                return 'C'
            return 'D'
        # Against mostly defective, always defect
        return 'D'

    # --- Opponent just cooperated ---
    # If we just defected and they still cooperate, resist over-exploiting too much.
    if last_me == 'D' and last_opp == 'C':
        # If opponent keeps cooperating despite our defection, resume cooperation
        return 'C'

    # Opponent cooperated, we cooperated last
    # If recent defection rate is elevated, be cautious
    if rec_rate < 0.5 and n >= 6:
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Mostly cooperative opponent: cooperate, occasional probe
    if opp_rate > 0.85:
        if mutual_cc >= 3 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Moderately cooperative: mostly cooperate, small chance to defect
    if opp_rate > 0.6:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Mixed opponents: tit-for-tat with slight forgiveness
    if rec_rate > opp_rate + 0.3 and w >= 6:
        # recent improvement in cooperation - reciprocate
        return 'C'
    if rec_rate < opp_rate - 0.3 and w >= 6:
        # recent deterioration - defend
        return 'D'

    if opp_rate > 0.4:
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    return 'D'
